<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Http\HttpError;use Hostider\Services\{Engine,Worker};use Hostider\Hosting\Pools;use Hostider\Providers\Mock\DurableCpanel;use Hostider\Providers\Contract\Operation;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();
function hostingFixture($db,int $quantity=1,int $capacity=10): array
{
    $f=serviceFixture($db,$quantity);$pools=new Pools($db,$f['config']);$pool=$pools->configure($f['product'],$capacity);$engine=new Engine($db,$f['config']);$ids=$engine->discover($f['order']['id'],$f['actor'],Id::uuid());$operations=[];foreach($ids as $id){$operations[]=$engine->repository->find($id,lock:false)['current_operation_id'];}return $f+compact('pool','engine','ids','operations','pools');
}
test('F3-C durable mock six-method contract persists resources and rejects changed replay',function()use($db): void{
    $f=hostingFixture($db);$adapter=new DurableCpanel($db,$f['config'],$f['pool']['server']);$create=new Operation(Id::uuid(),'createAccount',null,['service_id'=>$f['ids'][0],'package_name'=>'mock_basic','cycle'=>$f['line']['cycle']]);$result=$adapter->createAccount($create);same('SUCCESS',$result->status);same($result->externalResourceId,$adapter->createAccount($create)->externalResourceId);same(409,raises(HttpError::class,fn()=>$adapter->createAccount(new Operation($create->id,'createAccount',null,['tampered'=>true])))->status);
    foreach(['inspectAccount','suspendAccount','unsuspendAccount','changePackage','terminateAccount'] as $action){same('SUCCESS',$adapter->$action(new Operation(Id::uuid(),$action,$result->externalResourceId,['package_name'=>'mock_upgraded']))->status);}same('TERMINATED',$adapter->evidence($result->externalResourceId)['status']);raises(LogicException::class,fn()=>$db->transaction(fn()=>$adapter->inspectAccount(new Operation(Id::uuid(),'inspectAccount',$result->externalResourceId))));
});
test('F3-C worker activates only with bound independent inspect and immutable period evidence',function()use($db): void{
    $f=hostingFixture($db,2);$before=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();$worker=new Worker($db,$f['config']);foreach($f['operations'] as $id){same(true,$worker->once($f['actor'],$id));same(false,$worker->once($f['actor'],$id));}same($before,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());foreach($f['ids'] as $id){$service=$f['engine']->repository->find($id,lock:false);same('ACTIVE',$service['status']);$period=$db->execute('SELECT * FROM svc_periods WHERE id=?',[$service['current_period_id']])->fetch();same('VERIFIED',$period['status']);same(false,$period['starts_at']===null);raises(PDOException::class,fn()=>$db->execute('UPDATE svc_periods SET ends_at=DATE_ADD(ends_at,INTERVAL 1 DAY) WHERE id=?',[$period['id']]));same(1,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$id])->fetchColumn());}
});
test('F3-C timeout after physical create holds UNKNOWN and capacity without second account',function()use($db): void{
    $f=hostingFixture($db);$worker=new Worker($db,$f['config']);same(true,$worker->once($f['actor'],$f['operations'][0],'TIMEOUT_AFTER_CREATE'));same('UNKNOWN',$f['engine']->repository->find($f['ids'][0],lock:false)['status']);same(false,$worker->once($f['actor'],$f['operations'][0]));same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$f['ids'][0]])->fetchColumn());same('HELD',$db->execute('SELECT status FROM hosting_reservations WHERE operation_id=?',[$f['operations'][0]])->fetchColumn());same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$f['ids'][0]])->fetchColumn());
});
test('F3-C capacity stale health and missing capabilities fail before any dispatch',function()use($db): void{
    $f=hostingFixture($db,2,1);$worker=new Worker($db,$f['config']);same(true,$worker->once($f['actor'],$f['operations'][0]));same(409,raises(HttpError::class,fn()=>$worker->once($f['actor'],$f['operations'][1]))->status);same('PENDING',$db->execute('SELECT status FROM svc_operations WHERE id=?',[$f['operations'][1]])->fetchColumn());
    $f=hostingFixture($db);$db->execute('UPDATE hosting_servers SET observed_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 HOUR) WHERE id=?',[$f['pool']['server']]);same(409,raises(HttpError::class,fn()=>(new Worker($db,$f['config']))->once($f['actor'],$f['operations'][0]))->status);$db->execute("UPDATE hosting_servers SET observed_at=UTC_TIMESTAMP(6),capabilities='[]' WHERE id=?",[$f['pool']['server']]);same(409,raises(HttpError::class,fn()=>(new Worker($db,$f['config']))->once($f['actor'],$f['operations'][0]))->status);same(0,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_calls WHERE server_id=?',[$f['pool']['server']])->fetchColumn());
});
test('F3-C definite failure releases capacity and live WHM remains closed even with flags',function()use($db): void{
    $f=hostingFixture($db);same(true,(new Worker($db,$f['config']))->once($f['actor'],$f['operations'][0],'DEFINITIVE_FAILURE'));same('FAILED',$f['engine']->repository->find($f['ids'][0],lock:false)['status']);same('RELEASED',$db->execute('SELECT status FROM hosting_reservations WHERE operation_id=?',[$f['operations'][0]])->fetchColumn());$config=new \Hostider\Core\Config('production','https://test.example.invalid',$f['config']->key,$f['config']->dsn,'test','',true,true,true);same('G-C01_OPEN_LIVE_WHM_TRANSPORT_DISABLED',raises(RuntimeException::class,fn()=>(new \Hostider\Providers\WhmBoundary($config))->dispatch())->getMessage());same(403,raises(HttpError::class,fn()=>new DurableCpanel($db,$config,$f['pool']['server']))->status);
});
test('F3-C canonical outbox dispatch is idempotent and rejects fabricated local events',function()use($db): void{
    $f=hostingFixture($db);$sink=new \Hostider\Services\EventSink($db,$f['config']);same('FAILED',$sink->consume('services.execute',['operation_id'=>Id::uuid()]));same('FAILED',$sink->consume('services.action',['operation_id'=>$f['operations'][0]]));same('SUCCEEDED',$sink->consume('services.execute',['operation_id'=>$f['operations'][0]]));same('SUCCEEDED',$sink->consume('services.execute',['operation_id'=>$f['operations'][0]]));same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$f['ids'][0]])->fetchColumn());same('SUCCEEDED',$sink->consume('services.changed',['service_id'=>$f['ids'][0]]));
});
test('F3-C four independent workers commit exactly one mock create and one verified resource',function()use($db): void{
    require_once __DIR__.'/support/FixtureDirectory.php';$f=hostingFixture($db);$directory=dirname(__DIR__).'/storage/service-test-'.bin2hex(random_bytes(8));mkdir($directory,0700,true);$file=$directory.'/fixture.json';file_put_contents($file,json_encode(['key'=>$f['config']->key,'order'=>$f['order']['id'],'operation'=>$f['operations'][0]],JSON_THROW_ON_ERROR));$children=[];$worked=0;
    try{for($i=0;$i<4;++$i){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/services-child.php',$file,'work'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($p)){throw new RuntimeException('Child unavailable');}fclose($pipes[0]);$children[]=[$p,$pipes];}foreach($children as [$p,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($p));same('',$err);$worked+=json_decode($out,true,32,JSON_THROW_ON_ERROR)?1:0;}}finally{foreach($children as [$p,$pipes]){if(is_resource($p)){proc_terminate($p);foreach([1,2] as $fd){if(is_resource($pipes[$fd])){fclose($pipes[$fd]);}}proc_close($p);}}FixtureDirectory::remove($directory);}same(1,$worked);same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$f['ids'][0]])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$f['ids'][0]])->fetchColumn());same('ACTIVE',$f['engine']->repository->find($f['ids'][0],lock:false)['status']);
});
runTests();
